nodes.css:
.wrap { position: absolute; inset: 0; display: flex; flex-direction: column;
  align-items: center; justify-content: center; gap: 34px; }
.ask { font-family: Archivo, Inter, DejaVu Sans; font-size: 88px; font-weight: 800; letter-spacing: -0.035em;
  color: #f4f1ea; }
.ask em { font-style: normal; color: #d9a441; }
.ul { width: 260px; height: 5px; border-radius: 3px; background: #d9a441; transform-origin: left center;
  animation: draw 0.7s cubic-bezier(0.16,1,0.3,1) 0.55s both; }
.btn { display: flex; flex-direction: row; align-items: center; gap: 14px;
  padding: 18px 36px; border-radius: 999px; background: rgba(12,13,16,0.92);
  border: 1.5px solid #d9a441; }
.dot { width: 10px; height: 10px; border-radius: 999px; background: #d9a441; }
.txt { font-family: JetBrains Mono, DejaVu Sans Mono, monospace; font-size: 21px; font-weight: 700; letter-spacing: 0.2em; color: #f4f1ea; }
.sub { font-family: JetBrains Mono, DejaVu Sans Mono, monospace; font-size: 16px; letter-spacing: 0.24em; color: #9a978e; }
@keyframes draw { from { transform: scaleX(0) } to { transform: scaleX(1) } }
